    /// Skip downloading for checksum and binary path detection (faster but less informative)
    #[usage(long)]
    pub skip_download: bool,

    /// URL for downloading the tool
    ///
    /// Example: https://github.com/owner/repo/releases/download/v2.0.0/tool-linux-x64.tar.gz
    #[usage(long, short)]
    pub url: Option<String>,

    /// Version of the tool
    #[usage(long, default = "latest")]
    pub version: String,
}

#[derive(Debug, Default, Clone, Copy, usage_rs::ValueEnum)]
pub(super) enum ChecksumAlgorithm {
    #[default]
    Blake3,
    Sha256,
}

impl ChecksumAlgorithm {
    fn checksum(self, bytes: &[u8]) -> String {
        match self {
            Self::Blake3 => format!("blake3:{}", blake3::hash(bytes).to_hex()),
            Self::Sha256 => {
                let hash = Sha256::digest(bytes);
                format!("sha256:{}", hex::encode(hash))
            }
        }
    }
}

impl ToolStub {
    pub(super) async fn run(self) -> Result<()> {
        let stub_content = if self.fetch {
            self.fetch_checksums().await?
        } else if self.lock {
            self.lock_stub().await?
        } else {
            self.generate_stub().await?
        };

        // Before the stub is written, so a launcher that is not ours stops the run rather than
        // leaving a regenerated stub whose launcher was silently skipped. Same ordering, and the
        // same reason, as `task-stubs`.
        self.validate_windows_launcher(&stub_content)?;

        if let Some(parent) = self.output.parent() {
            file::create_dir_all(parent)?;
        }

        file::write(&self.output, &stub_content)?;
        file::make_executable(&self.output)?;
        let launcher = self.write_windows_launcher(&stub_content)?;

        // Both lines printed here rather than where each file is written, so the launcher cannot
        // end up announced with a different verb than the stub it belongs to.
        let verb = if self.fetch || self.lock {
            "Updated"
        } else {
            "Generated"
        };
        miseprintln!("{verb} tool stub: {}", display_path(&self.output));
        if let Some(launcher) = launcher {
            miseprintln!("{verb} Windows launcher: {}", display_path(&launcher));
        }
        Ok(())
    }

    /// Write the `.cmd` next to a stub that could run on Windows.
    ///
    /// Windows cannot execute the stub itself: it is a shebang script, and `CreateProcess` will not
    /// run one. The stub's own machinery works there — `mise tool-stub <file>` does the right thing
    /// — so all that is missing is something Windows will launch.
    ///
    /// Written on every host, not just Windows, because the case worth fixing is a stub authored on
    /// Linux and committed: the Windows user who runs it is not its author and has no way to
    /// regenerate it (they do not have the original `--url`/`--version`). A host-OS check would
    /// never fire for them.
    ///
    /// Returns the launcher when one was written, so the caller can name it. Removing a stale one
    /// stays silent: this is the path that reports what the command produced, and a deletion is a
    /// different kind of message.
    fn write_windows_launcher(&self, stub_content: &str) -> Result<Option<PathBuf>> {
        let Some(launcher) = super::windows_launcher_path(&self.output) else {
            return Ok(None);
        };
        if wants_windows_launcher(stub_content) {
            file::write(&launcher, &*WINDOWS_LAUNCHER)?;
            return Ok(Some(launcher));
        } else if file::read_to_string(&launcher).is_ok_and(|c| super::is_generated_launcher(&c)) {
            // A stub that used to ship for Windows and no longer does would otherwise keep a
            // launcher that still runs, contradicting the platforms it now declares. Recognised by
            // the marker rather than by comparing text, so a launcher written by an older mise --
            // whose body differed -- is still cleaned up; a launcher the user wrote is left alone.
            file::remove_file(&launcher)?;
        }
        Ok(None)
    }

    /// Refuse to replace a `.cmd` beside the stub that mise did not write.
    ///
    /// `--output` is the user's choice, so `<stub>.cmd` is a name a project may already be using
    /// for a script of its own, and nothing about that name says mise owns it. The stub itself is
    /// different: the user named it, so overwriting it is what they asked for.
    fn validate_windows_launcher(&self, stub_content: &str) -> Result<()> {
        if !wants_windows_launcher(stub_content) {
            return Ok(());
        }
        let Some(launcher) = super::windows_launcher_path(&self.output) else {
            return Ok(());
        };
        match fs::symlink_metadata(&launcher) {
            Ok(metadata) if metadata.file_type().is_file() => {
                if !super::is_generated_launcher(&file::read_to_string(&launcher)?) {
                    bail!(
                        "cannot write Windows launcher because {} is not a generated launcher",
                        display_path(&launcher)
                    );
                }
            }
            Ok(_) => bail!(
                "cannot write Windows launcher because {} is not a regular file",
                display_path(&launcher)
            ),
            Err(err) if matches!(err.kind(), ErrorKind::NotFound | ErrorKind::NotADirectory) => {}
            Err(err) => return Err(err.into()),
        }
        Ok(())
    }

    fn get_tool_name(&self) -> String {
        self.output
            .file_name()
                                platform_table["checksum"] = toml_edit::value(&checksum);

                                // Create size entry with human-readable comment
                                let mut size_item = toml_edit::value(size as i64);
                                if let Some(value) = size_item.as_value_mut() {
                                    let formatted_comment = format_size_comment(size);
                                    value.decor_mut().set_suffix(formatted_comment);
                                }
                                platform_table["size"] = size_item;
                            }
                            Err(e) => {
                                // Log error but continue with other platforms
                                eprintln!(
                                    "Warning: Failed to fetch checksum for platform '{platform_name}': {e}"
                                );
                            }
                        }
                    }
                }
            }
        }

        let toml_content = doc.to_string();

        // Check if original was a bootstrap stub and preserve that format
        if is_bootstrap_stub(&content) {
            self.wrap_with_bootstrap(&toml_content).await
        } else {
            let mut output = vec![
                "#!/usr/bin/env -S mise tool-stub".to_string(),
                "".to_string(),
            ];

            output.push(toml_content);

            Ok(output.join("\n"))
        }
    }
}

fn lock_stub_target_platforms() -> Result<Vec<Platform>> {
    if let Some(configured) = Settings::get().lockfile_platforms()? {
        let mut platforms: BTreeSet<Platform> = configured.into_iter().collect();
        platforms.insert(Platform::current());
        Ok(platforms.into_iter().collect())
    } else {
        Ok(Platform::common_platforms())
    }
}

/// Check if content is a bootstrap stub
fn is_bootstrap_stub(content: &str) -> bool {
    content.contains("# MISE_TOOL_STUB:") && content.contains("# :MISE_TOOL_STUB")
}

fn format_size_comment(bytes: u64) -> String {
    format!(" # {}", ByteSize::b(bytes).display().iec())
}

/// Extract TOML content from a stub file (handles both regular and bootstrap stubs)
fn extract_toml_from_stub(content: &str) -> String {
    // Check if this is a bootstrap stub by looking for comment markers
    if is_bootstrap_stub(content) {
        // Bootstrap stub: extract TOML between comment markers
        let start_marker = "# MISE_TOOL_STUB:";
        let end_marker = "# :MISE_TOOL_STUB";

        if let (Some(start_pos), Some(end_pos)) =
            (content.find(start_marker), content.find(end_marker))
            && start_pos < end_pos
        {
            let between = &content[start_pos + start_marker.len()..end_pos];
            return between
                .lines()
                .map(|line| line.strip_prefix("# ").unwrap_or(line))
                .collect::<Vec<_>>()
                .join("\n")
                .trim()
                .to_string();
        }
        String::new()
    } else {
        // Regular stub: skip shebang and comments at the start
        content
            .lines()
            .skip_while(|line| line.starts_with('#') || line.trim().is_empty())
            .collect::<Vec<_>>()
            .join("\n")
    }
}

/// The Windows launcher written beside an eligible stub.
///
/// `%~dpn0` is the launcher's own drive+path+name with the extension dropped, which is exactly the
/// stub sitting next to it — so the stub's name never has to be interpolated in. That matters
/// beyond tidiness: a name containing `%` would otherwise be expanded by `cmd.exe` as an
/// environment variable and hand `mise tool-stub` the wrong path.
///
/// `mise` comes off PATH, the same assumption the shebang already makes. Argument handling and the
/// exit code are [`super::windows_launcher_body`]'s job — `%*` alone does not carry an argument
/// containing `& ^ | " < >`, because cmd parses its command line before the batch file runs.
///
/// Cleanup does not compare against this string: [`super::is_generated_launcher`] recognises a
/// launcher by its marker and shape, so one written by an older mise is still removed, and a
/// hand-written `.cmd` still never is.
static WINDOWS_LAUNCHER: LazyLock<String> =
    LazyLock::new(|| super::windows_launcher_body("mise tool-stub \"%~dpn0\""));

/// Whether a stub warrants a Windows `.cmd` launcher.
///
/// Judged from the stub itself rather than the host OS — see [`ToolStub::write_windows_launcher`]
/// for why. A stub earns one unless its author ruled Windows out:
///
/// - lists a `[platforms.*]` table with a windows entry → yes
/// - lists `[platforms.*]` tables but none for windows → no, this tool does not ship for Windows
/// - lists no platforms at all (`tool = "python"`, or a bare `url`) → yes, nothing was ruled out
///
/// The stub's *name* is judged separately, by [`super::windows_launcher_path`].
fn wants_windows_launcher(stub_content: &str) -> bool {
    // Via the same extractor the rest of this file uses, so a --bootstrap stub (TOML embedded in a
    // bash wrapper) is read correctly rather than failing to parse and falling through.
    let Ok(doc) = extract_toml_from_stub(stub_content).parse::<DocumentMut>() else {
        // Unparseable stubs are the generator's problem, not this function's; err towards the
        // launcher so a Windows user is not silently left without one.
        return true;
    };
    let Some(platforms) = doc.get("platforms").and_then(|p| p.as_table_like()) else {
        return true;
    };
    if platforms.is_empty() {
        return true;
    }
    // Parsed rather than prefix-matched: `windows-arm64` counts, and a future qualifier such as
    // `windows-x64-msvc` keeps counting.
    platforms
        .iter()
        .filter_map(|(key, _)| Platform::parse(key).ok())
        .any(|p| p.os == "windows")
}

#[cfg(test)]
mod tests {
    use super::ChecksumAlgorithm;

    #[test]
    fn checksum_algorithm_formats_blake3() {
            ChecksumAlgorithm::Sha256.checksum(b""),
            "sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
        );
    }
}

#[cfg(test)]
mod windows_launcher_tests {
    use super::*;

    #[test]
    fn a_stub_that_ships_for_windows_gets_a_launcher() {
        let stub = r#"
[platforms.linux-x64]
url = "https://example.com/tool-linux.tar.gz"

[platforms.windows-x64]
url = "https://example.com/tool-windows.zip"
bin = "tool.exe"
"#;
        assert!(wants_windows_launcher(stub));

        // arm64-only windows counts too — this is why the check parses the platform instead of
        // looking for the string "windows-x64"
        let arm_only = r#"
[platforms.windows-arm64]
url = "https://example.com/tool-windows-arm64.zip"
"#;
        assert!(wants_windows_launcher(arm_only));
    }

    #[test]
    fn a_stub_with_no_windows_platform_does_not() {
        let stub = r#"
[platforms.linux-x64]
url = "https://example.com/tool-linux.tar.gz"

[platforms.macos-arm64]
url = "https://example.com/tool-macos.tar.gz"
"#;
        assert!(!wants_windows_launcher(stub));
    }

    #[test]
    fn a_stub_that_names_no_platforms_gets_one() {
        // nothing was ruled out, and these run anywhere mise does
        assert!(wants_windows_launcher(
            "version = \"1.0.0\"\ntool = \"python\"\n"
        ));
        assert!(wants_windows_launcher(
            "url = \"https://example.com/thing.tar.gz\"\n"
        ));
    }

    // The executable-extension guard lives in `super::windows_launcher_path` now, and is tested
    // there — both stub kinds share it.
}
#!/usr/bin/env bash
# shellcheck disable=SC2103

# Test mise generate tool-stub --lock functionality

# Disable GPG verification to avoid test failures
export MISE_GPG_VERIFY=false

# Create test project directory
mkdir -p generate_tool_stub_lock_test/bin
cd generate_tool_stub_lock_test

# Test 1: Lock a non-HTTP tool stub (github:jdx/tiny)
cat >bin/tiny <<'EOF'
#!/usr/bin/env -S mise tool-stub

tool = "github:jdx/tiny"
version = "1"
bin = "bin/tiny"
EOF
chmod +x bin/tiny

assert_succeed "mise generate tool-stub bin/tiny --lock"

# Verify version was pinned to an exact version (not just "1")
assert_not_contains "cat bin/tiny" 'version = "1"'
assert_contains "cat bin/tiny" 'version = "1.'

# Verify [lock.platforms.*] sections were added
assert_contains "cat bin/tiny" "[lock.platforms."
assert_contains "cat bin/tiny" "url ="
assert_contains "cat bin/tiny" "checksum ="

# Verify the shebang is preserved
assert_contains "cat bin/tiny" "#!/usr/bin/env -S mise tool-stub"

# Verify the tool field is preserved
assert_contains "cat bin/tiny" 'tool = "github:jdx/tiny"'

# Test 2: Bump version with --lock --version
assert_succeed "mise generate tool-stub bin/tiny --lock --version 2"

# Verify version was bumped
assert_contains "cat bin/tiny" 'version = "2.'
assert_not_contains "cat bin/tiny" 'version = "1.'

# Verify lock sections still present after bump
assert_contains "cat bin/tiny" "[lock.platforms."
assert_contains "cat bin/tiny" "url ="

# Test 3: Execute the locked stub to verify it works
if mise version | grep -q "windows-"; then
  echo "Skipping locked stub execution on Windows because jdx/tiny has no Windows release asset"
else
  assert_contains "mise tool-stub bin/tiny" "tiny v2."
fi

# Test 4: Re-lock preserves version and respects lockfile_platforms
locked_version=$(grep 'version = ' bin/tiny | head -1 | sed 's/.*"\(.*\)".*/\1/')
export MISE_LOCKFILE_PLATFORMS=macos-arm64,linux-x64
export MISE_OS=macos
export MISE_ARCH=x64
assert_succeed "mise generate tool-stub bin/tiny --lock"

# Version should be the same after re-locking
assert_contains "cat bin/tiny" "version = \"$locked_version\""

assert_contains "cat bin/tiny" "lock.platforms.macos-arm64"
assert_contains "cat bin/tiny" "lock.platforms.linux-x64"
assert_contains "cat bin/tiny" "lock.platforms.macos-x64"
assert_not_contains "cat bin/tiny" "lock.platforms.windows-x64"
unset MISE_LOCKFILE_PLATFORMS MISE_OS MISE_ARCH

# Test 5: Lock fails on nonexistent file
assert_fail "mise generate tool-stub bin/nonexistent --lock"

echo "All tool-stub lock tests passed!"
