   264	            return None;
   265	        }
   266	
   267	        match file::read_to_string(&cache_path) {
   268	            Ok(content) => {
   269	                let bin_path = PathBuf::from(content.trim());
   270	                // Verify the cached binary still exists
   271	                if bin_path.exists() {
   272	                    Some(bin_path)
   273	                } else {
   274	                    // Clean up stale cache (missing binary)
   275	                    let _ = file::remove_file(&cache_path);
