   113	/// Extract TOML content from a bootstrap script's comment block
   114	/// Looks for content between `# MISE_TOOL_STUB:` and `# :MISE_TOOL_STUB` markers
   115	fn extract_toml_from_bootstrap(content: &str) -> Option<String> {
   116	    let start_marker = "# MISE_TOOL_STUB:";
   117	    let end_marker = "# :MISE_TOOL_STUB";
   118	
   119	    let start_pos = content.find(start_marker)?;
   120	    let end_pos = content.find(end_marker)?;
   121	
   122	    if start_pos >= end_pos {
   123	        return None;
   124	    }
   125	
   126	    // Extract content between markers (skip the start marker line)
   127	    let between = &content[start_pos + start_marker.len()..end_pos];
   128	
   129	    // Remove leading `# ` from each line to get the original TOML
   130	    let toml = between
   131	        .lines()
   132	        .map(|line| line.strip_prefix("# ").unwrap_or(line))
   133	        .collect::<Vec<_>>()
   134	        .join("\n");
   135	
   136	    Some(toml.trim().to_string())
   137	}
