   186	    // Create a ToolRequest directly using ToolVersionOptions
   187	    pub(crate) fn to_tool_request(&self, stub_path: &Path) -> Result<ToolRequest> {
   188	        use crate::cli::args::BackendArg;
   189	
   190	        let mut backend_arg = BackendArg::from(&self.tool_name);
   191	        let source = ToolSource::ToolStub(stub_path.to_path_buf());
   192	
   193	        // Create ToolVersionOptions from our fields
   194	        let mut opts = self.opts.clone();
   195	        opts.shift_remove("tool"); // Remove tool field since it's handled separately
   196	
   197	        // Add bin field if present
   198	        if let Some(bin) = &self.bin {
   199	            opts.insert("bin".to_string(), toml::Value::String(bin.clone()));
   200	        }
   201	
   202	        let options = ToolVersionOptions {
   203	            core: CoreToolOptions {
   204	                os: self.os.clone(),
   205	                depends: None,
   206	                install_env: self.install_env.clone(),
   207	                ..Default::default()
   208	            },
   209	            opts: opts.into(),
   210	        };
   211	
   212	        // Set options on the BackendArg so they're available to the backend
   213	        backend_arg.set_opts(Some(options.clone()));
   214	
   215	        // For HTTP backend with "latest" version, use URL+checksum hash as version for stability
   216	        let version = if self.tool_name.starts_with("http:") && self.version == "latest" {
   217	            if let Some(url) = lookup_platform_key(&options, "url")
   218	                .or_else(|| options.get("url").map(|s| s.to_string()))
   219	            {
   220	                // Include checksum in hash calculation for better version stability
   221	                let checksum = lookup_platform_key(&options, "checksum")
   222	                    .or_else(|| options.get("checksum").map(|s| s.to_string()))
   223	                    .unwrap_or_default();
   224	                let hash_input = format!("{url}:{checksum}");
   225	                // Use first 8 chars of URL+checksum hash as version
   226	                format!("url-{}", &hash::hash_to_str(&hash_input)[..8])
   227	            } else {
   228	                self.version.clone()
   229	            }
   230	        } else {
   231	            self.version.clone()
   232	        };
   233	
   234	        ToolRequest::new_with_options(backend_arg.into(), &version, options, source)
   235	    }
   236	}
