   238	// Cache just stores the binary path as a raw string
   239	// The mtime is already encoded in the cache key, so no need to store it
   240	
   241	struct BinPathCache;
   242	
   243	impl BinPathCache {
   244	    fn cache_key(stub_path: &Path) -> Result<String> {
   245	        let path_str = stub_path.to_string_lossy();
   246	        let mtime = stub_path.metadata()?.modified()?;
   247	        let mtime_str = format!(
   248	            "{:?}",
   249	            mtime
   250	                .duration_since(std::time::UNIX_EPOCH)
   251	                .unwrap_or_default()
   252	                .as_secs()
   253	        );
   254	        Ok(hash::hash_to_str(&format!("{path_str}:{mtime_str}")))
   255	    }
   256	
   257	    fn cache_file_path(cache_key: &str) -> PathBuf {
   258	        dirs::CACHE.join("tool-stubs").join(cache_key)
   259	    }
   260	
   261	    fn load(cache_key: &str) -> Option<PathBuf> {
   262	        let cache_path = Self::cache_file_path(cache_key);
   263	        if !cache_path.exists() {
   264	            return None;
   265	        }
   266	
   267	        match file::read_to_string(&cache_path) {
   268	            Ok(content) => {
   269	                let bin_path = PathBuf::from(content.trim());
   270	                // Verify the cached binary still exists
   271	                if bin_path.exists() {
   272	                    Some(bin_path)
   273	                } else {
   274	                    // Clean up stale cache (missing binary)
   275	                    let _ = file::remove_file(&cache_path);
   276	                    None
   277	                }
   278	            }
   279	            Err(_) => None,
   280	        }
   281	    }
   282	
   283	    fn save(bin_path: &Path, cache_key: &str) -> Result<()> {
   284	        let cache_path = Self::cache_file_path(cache_key);
   285	
   286	        if let Some(parent) = cache_path.parent() {
   287	            file::create_dir_all(parent)?;
   288	        }
   289	
   290	        file::write(&cache_path, bin_path.to_string_lossy().as_bytes())?;
   291	        Ok(())
   292	    }
   293	}
